/* Parse Facebook Messenger webhook -> one item per incoming message
 * Output: { userId, text, messageType, messageId, mediaUrl?, mediaPreviewUrl?, seq }
 * ???????????? echo (?????????????????????????????????????????????????????????????????????????????????????????????) ????????? event ????????????????????????????????????????????????
 */
const body = $('Webhook').first().json.body || {};
const entries = Array.isArray(body.entry) ? body.entry : [];
const out = [];
let seq = 0;

for (const entry of entries) {
  const messaging = Array.isArray(entry.messaging) ? entry.messaging : [];
  for (const m of messaging) {
    if (!m || !m.message) { continue; }
    if (m.message.is_echo) { continue; }
    const userId = (m.sender && m.sender.id) ? m.sender.id : '';
    if (!userId) { continue; }

    const msg = m.message;
    const atts = Array.isArray(msg.attachments) ? msg.attachments : [];
    let mtype = 'text';
    let text = '';
    if (atts.length > 0) {
      const a = atts[0];
      const t = a.type || 'file';
      mtype = t;
      if (t === 'image')       { text = '[?????????]'; }
      else if (t === 'video')  { text = '[??????????????????]'; }
      else if (t === 'audio')  { text = '[???????????????]'; }
      else if (t === 'file')   { text = '[????????????]'; }
      else if (t === 'location') { text = '[?????????????????????]'; }
      else                     { text = '[' + t + ']'; }
    } else if (typeof msg.text === 'string') {
      text = msg.text.trim();
    }
    if (!text) { continue; }

    const item = {
      userId: userId,
      text: text,
      messageType: mtype,
      messageId: msg.mid || '',
      seq: seq++,
    };
    if (atts.length > 0 && atts[0].payload && atts[0].payload.url) {
      item.mediaUrl = atts[0].payload.url;
      item.mediaPreviewUrl = atts[0].payload.url;
    }
    out.push({ json: item });
  }
}
return out;

/* Forward to ChatDesk incoming.php (channel=fb) ??????????????? media URL ??????????????????????????? FB ????????? ??? */
const cfg      = $('Set Config').first().json;
const events   = $('Parse FB Events').all();   // ??????????????????????????? parse ?????? (???????????????????????? entry order)
const profiles = $input.all();                 // Get FB Profile output 1:1 ???????????????????????? item

const out = [];
for (let i = 0; i < events.length; i++) {
  const ev = events[i].json || {};
  const pr = (profiles[i] && profiles[i].json) ? profiles[i].json : {};
  const firstName   = pr.first_name || '';
  const lastName    = pr.last_name || '';
  const displayName = [firstName, lastName].filter(Boolean).join(' ');
  const pictureUrl  = pr.profile_pic || '';

  let botEnabled = true;
  const payload = {
    userId: ev.userId,
    text: ev.text,
    sender: 'customer',
    messageId: ev.messageId,
    messageType: ev.messageType,
    channel: 'fb',
  };
  if (ev.mediaUrl) {
    payload.mediaUrl = ev.mediaUrl;
    payload.mediaPreviewUrl = ev.mediaPreviewUrl || ev.mediaUrl;
  }
  if (displayName) { payload.displayName = displayName; }
  if (pictureUrl)  { payload.pictureUrl = pictureUrl; }
  if (cfg.CHATDESK_SECRET) { payload.secret = cfg.CHATDESK_SECRET; }

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: payload,
    });
    botEnabled = !(res && res.botEnabled === false);
  } catch (err) {
    botEnabled = true;
  }

  out.push({ json: {
    userId: ev.userId,
    text: ev.text,
    displayName: displayName,
    botEnabled: botEnabled,
    isText: ev.messageType === 'text',
  } });
}

return out;

/* Take AI Agent output, strip thinking tags, attach userId from Send to ChatDesk */
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let userId = '';
  try {
    userId = $('Send to ChatDesk').itemMatching(i).json.userId || '';
  } catch (err) {
    userId = '';
  }

  const raw = items[i].json.output || items[i].json.text || '';
  const replyText = String(raw).replace(/<think>[\s\S]*?<\/think>/g, '').trim();

  if (userId && replyText) {
    out.push({ json: { userId: userId, replyText: replyText } });
  }
}

return out;

/* Build Facebook Messenger Graph API payload from bot reply (text only) */
const items = $input.all();
const out = [];
for (const it of items) {
  const j = it.json || {};
  if (!j.userId || !j.replyText) { continue; }
  out.push({ json: {
    recipient: { id: j.userId },
    message: { text: j.replyText },
    messaging_type: 'RESPONSE',
  } });
}
return out;

/* Save bot reply into ChatDesk (channel=fb) */
const cfg = $('Set Config').first().json;
for (const item of $('Build Reply').all()) {
  const j = item.json || {};
  if (!j.userId || !j.replyText) { continue; }
  const payload = { userId: j.userId, text: j.replyText, sender: 'bot', channel: 'fb' };
  if (cfg.CHATDESK_SECRET) { payload.secret = cfg.CHATDESK_SECRET; }
  const res = await this.helpers.httpRequest({
    method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: payload,
  });
  if (!res || res.ok !== true) {
    throw new Error('ChatDesk save failed: ' + JSON.stringify(res));
  }
}
return $input.all();

